from lib import *
r=[]
r.append(R(6914404,"ग्रिल्ड स्कैलप्स, मोटी कटी सालसा वर्दे के साथ","यह कम वसा और कम सोडियम वाला, लेकिन प्रोटीन से भरपूर शानदार समुद्री भोजन है। सालसा वर्दे के तीखेपन को संतुलित करने के लिए इसे कुछ स्ट्रॉबेरी के टुकड़ों वाले सरल अरुगुला सलाद के साथ परोसकर देखें।","4","3 स्कैलप्स और 1/2 कप सालसा",
["1/2 पाउंड टमाटिलो (छिलका हटाए, धोए, छोटे टुकड़ों में कटे हुए)","1 छोटी हलापेन्यो मिर्च (बीज और नसें निकालकर बारीक कटी हुई)","1/4 कप ताज़ा हरा धनिया (कटा हुआ)","1 मध्यम ज़ुकीनी (बीज निकालकर छोटे टुकड़ों में कटी हुई)","2 बड़े चम्मच नीबू का रस","1 छोटा चम्मच शहद या 1/2 पैकेट कृत्रिम मिठास","2 फाँक लहसुन (बारीक कटा हुआ)","12 बड़े स्कैलप्स (किनारे की पट्टी हटाई हुई (नोट: ताज़े या बिना प्रिज़र्वेटिव वाले सी स्कैलप्स सबसे अच्छे होते हैं))","1 बड़ा चम्मच जैतून का तेल","1/4 छोटा चम्मच नमक","1/4 छोटा चम्मच काली मिर्च"],
["इनडोर या आउटडोर ग्रिल तैयार करें।","एक मध्यम कटोरे में टमाटिलो, हलापेन्यो, हरा धनिया, ज़ुकीनी, नीबू का रस, स्टीविया और लहसुन को मिलाएँ। मिलाकर एक तरफ़ रख दें।","स्कैलप्स को पेपर टॉवल से थपथपाकर सुखा लें। उन्हें एक मध्यम कटोरे में जैतून का तेल, नमक और काली मिर्च के साथ मिलाएँ।","स्कैलप्स को समतल तरफ़ नीचे करके ग्रिल पर रखें। बीच-बीच में पलटते हुए, हल्के जलने के निशान आने और बस पकने तक ग्रिल करें, प्रति तरफ़ लगभग 2 मिनट। स्कैलप्स को मोटी कटी सालसा वर्दे के साथ परोसें।"]))
r.append(R(6914849,"धीमी आँच पर रोस्ट की हुई साइट्रस कॉड मछली","कॉड जैसी सफ़ेद मछली का स्वाद नाज़ुक होता है जिससे वह जिन सामग्रियों के साथ पकती है उनका स्वाद सोख लेती है। इसे नीबू और संतरे के टुकड़ों और सौंफ़ कंद के साथ रोस्ट करने से मछली को ताज़ा, खट्टे फलों जैसा स्वाद मिलता है।","4","4 औंस मछली",
["1/4 छोटा चम्मच काली मिर्च","1/2 छोटा चम्मच कोशर नमक","2 बड़े चम्मच जैतून का तेल","4 टहनी ताज़ा थाइम","1 पाउंड कॉड फ़िलेट (4 फ़िलेट, हर एक लगभग 4 औंस)","1/2 छोटी हलापेन्यो मिर्च (आधी कटी, बीज निकाली और पतली कटी हुई)","1 मध्यम नीबू (बिना छिले, पतले कटे हुए, बीज निकाले हुए)","1 मध्यम संतरा (बिना छिले, पतले कटे हुए, बीज निकाले हुए)","1 साबुत सौंफ़ कंद (पतला कटा हुआ)"],
["ओवन को 300°F पर पहले से गरम करें। 9x13 इंच के बेकिंग पैन में सौंफ़ कंद, संतरे और नीबू के टुकड़े और हलापेन्यो मिर्च को मिलाएँ।","कॉड के टुकड़ों को साइट्रस मिश्रण के बगल में रखें। मछली पर थाइम की टहनियाँ बिखेरें। ऊपर से जैतून का तेल डालें और नमक व काली मिर्च छिड़कें।","मछली को 25 से 30 मिनट तक, या अपारदर्शी होने और पूरी तरह पकने तक रोस्ट करें। मछली को रोस्टेड सौंफ़ कंद और साइट्रस के साथ परोसें।"]))
r.append(R(6915533,"किफ़ायती सब्ज़ियों का स्ट्यू, साबुत गेहूँ के डम्पलिंग के साथ","पतझड़ में गरमागरम, स्वादिष्ट सूप से बेहतर क्या हो सकता है? यह किफ़ायती रेसिपी काफ़ी आसान है।","8","1 1/2 कप स्ट्यू + 1 डम्पलिंग",
["1 बड़ा चम्मच जैतून का तेल","1 साबुत सौंफ़ कंद (कटा हुआ)","1 मध्यम प्याज़ (कटा हुआ)","2 डंठल सेलेरी (कटी हुई)","4 कप बटरनट स्क्वैश (कटा हुआ)","1 छोटा चम्मच पिसी सेज","4 कप कम सोडियम वाला चिकन ब्रॉथ (कम सोडियम)","4 कप पानी","2 छोटे चम्मच नमक (बाँटकर इस्तेमाल करें)","3/4 छोटा चम्मच काली मिर्च (बाँटकर इस्तेमाल करें)","2 तेज पत्ते","4 कप केल (कटी हुई, 1 गुच्छा डंठल हटाकर कटा हुआ)","1 कप साबुत गेहूँ का आटा","1/2 कप मैदा (सर्व-उपयोगी आटा)","1 बड़ा चम्मच बेकिंग पाउडर","1 छोटा चम्मच हर्ब्स डी प्रोवेंस ((या सूखी सेज))","1 बड़ा अंडा","1/2 कप सादा वसा रहित ग्रीक दही"],
["एक बड़े सूप के बरतन में मध्यम-तेज़ आँच पर तेल डालें।","तेल में सौंफ़ कंद, प्याज़ और सेलेरी डालें और प्याज़ के पारदर्शी होने तक भूनें (लगभग 4-5 मिनट)। बटरनट स्क्वैश, सेज, चिकन ब्रॉथ, पानी, 1 छोटा चम्मच नमक (वैकल्पिक), 1/2 छोटा चम्मच काली मिर्च और तेज पत्ते डालें। उबाल आने दें और फिर धीमी आँच पर पकाएँ।","स्ट्यू को 20 मिनट धीमी आँच पर पकाएँ, फिर केल डालें और 10 मिनट और पकाएँ।","जब स्ट्यू पक रहा हो, तब डम्पलिंग की सभी सामग्री को फेंटकर गाढ़ा घोल बनाएँ। एक तरफ़ रख दें।","केल को 10 मिनट पकाने के बाद तेज पत्ता निकाल दें।","1/4 कप के माप से स्ट्यू के ऊपर डम्पलिंग रखें, कुल 8 डम्पलिंग बनाएँ। डम्पलिंग को स्ट्यू के ऊपर रखने के बाद न चलाएँ। ढक दें और धीमी आँच पर 10 मिनट तक पकाएँ, जब तक कि डम्पलिंग अंदर तक पक न जाएँ और फूल न जाएँ।"]))
r.append(R(6916353,"संतरा और अखरोट सलाद","इस हल्के सलाद को इस साल अपनी छुट्टियों की सभा में सेहतमंद विकल्प के रूप में परोसें। यह आपको कुछ ताज़े फल और सब्ज़ियाँ देगा, जो आमतौर पर छुट्टियों के खाने में अक्सर नहीं होतीं!","8","लगभग 2/3 कप संतरा-गाजर का मिश्रण + 1 कप हरी पत्तियाँ",
["2 बड़े संतरे (छिले और फाँकों में अलग किए हुए)","8 कप मिली-जुली सलाद की हरी पत्तियाँ","1 छोटा लाल प्याज़ (पतला कटा हुआ)","2 बड़ी गाजर (छिली और पतली कटी हुई)","2 बड़े चम्मच ताज़ा संतरे का रस","2 बड़े चम्मच नीबू का रस (ताज़ा)","1 बड़ा चम्मच शहद","2 छोटे चम्मच डिजॉन सरसों","1/4 कप अखरोट का तेल","1/8 छोटा चम्मच काली मिर्च (स्वादानुसार)","1/4 कप अखरोट के टुकड़े"],
["हरी पत्तियों को थाली में रखें। ऊपर गाजर, प्याज़ और संतरे डालें।","विनेग्रेट के लिए, संतरे और नीबू का रस, शहद और सरसों को फेंटकर मिलाएँ। लगातार फेंटते हुए धीरे-धीरे पतली धार में तेल डालें।","विनेग्रेट को सलाद पर डालें। स्वादानुसार काली मिर्च डालें और ऊपर से अखरोट डालें।"]))
r.append(R(6917127,"किफ़ायती गर्मियों की सब्ज़ियों का फ्रिटाटा","यह फ्रिटाटा आपके दिन में ज़्यादा सब्ज़ियाँ शामिल करने का बढ़िया तरीका है और इसका आनंद ब्रंच या रात के खाने में लिया जा सकता है। अंडे की सफ़ेदी और साबुत अंडों के मेल का इस्तेमाल करके, आप संतृप्त वसा और कोलेस्ट्रॉल कुछ कम कर देते हैं।","4","2 टुकड़े",
["1 बड़ा चम्मच जैतून का तेल","8 औंस सफ़ेद (बटन) मशरूम (कटे हुए)","1 मध्यम लाल शिमला मिर्च (बीज निकालकर कटी हुई)","1 छोटा प्याज़ (कटा हुआ)","3 कप पालक","2 बड़े अंडे","5 बड़े अंडों की सफ़ेदी","1/4 कप स्किम दूध","1/2 छोटा चम्मच नमक (वैकल्पिक)","1/2 छोटा चम्मच काली मिर्च","1/4 छोटा चम्मच लाल मिर्च पाउडर","1 बड़ा चम्मच ताज़ी तुलसी (कटी हुई)"],
["ओवन को 350 डिग्री F पर पहले से गरम करें।","ओवन में रखने लायक नॉन-स्टिक सॉते पैन में मध्यम-तेज़ आँच पर जैतून का तेल डालें।","मशरूम डालें और मशरूम से निकला सारा तरल सूखने तक भूनें।","शिमला मिर्च, प्याज़ और पालक डालें और सब्ज़ियों के नरम होने और तरल के सूखने तक भूनें।","एक मध्यम कटोरे में अंडे, अंडे की सफ़ेदी, दूध, नमक (वैकल्पिक), काली मिर्च, लाल मिर्च पाउडर और तुलसी को फेंटें। सब्ज़ियों पर डालें और अंडों के जमना शुरू होने तक चलाएँ।","स्पैचुला से फ्रिटाटा की ऊपरी सतह को चिकना करें और 20 मिनट या अंडों के जमने तक बेक करने के लिए ओवन में रखें।","फ्रिटाटा को पैन से प्लेट पर सरकाएँ और पाई की तरह 8 टुकड़ों में काट लें।"]))
r.append(R(6917203,"अनार रास्पबेरी स्मूदी बाउल","इस सुबह की स्मूदी बाउल में सिल्कन टोफू प्रोटीन और सेहतमंद वसा से भरपूर मलाईदार आधार बनाता है। अनार के दानों और म्यूज़्ली (सेहतमंद साबुत अनाज और सूखे फलों का सीरियल) से सजा यह स्मूदी बाउल आपका पेट भरेगा और पूरी सुबह आपको ऊर्जावान रखेगा। यह वीगन, शाकाहारी और कम वसा वाली रेसिपी है।","2","1 कप",
["8 औंस सिल्कन टोफू (पानी निथारा हुआ)","2 बड़े चम्मच अनार का रस","1/2 कप रास्पबेरी (फ्रोज़न)","2 छोटे चम्मच शुगर-फ्री सिरप","1 औंस अनार के दाने","1/4 कप म्यूज़्ली"],
["टोफू, अनार का रस, रास्पबेरी और सिरप को ब्लेंडर या फ़ूड प्रोसेसर में रखें। मलाईदार और गुलाबी रंग का होने तक हाई पर ब्लेंड करें।","मिश्रण को 2 कटोरों में बाँट दें। हर एक के ऊपर आधे अनार के दाने और 2 बड़े चम्मच म्यूज़्ली डालें।"]))
r.append(R(6918726,"5 सामग्री वाले ब्लूबेरी प्रोटीन मफ़िन","धोखा न खाएँ। ये 5 सामग्री वाले ब्लूबेरी प्रोटीन मफ़िन आकार में छोटे हो सकते हैं, लेकिन ये यकीनन स्वादिष्ट हैं! यह रेसिपी ताज़ी, मीठी-खट्टी ब्लूबेरी को बादाम बटर और वनीला ग्रीक वसा रहित दही के गरम स्वाद के साथ मिलाकर आपके आहार में ज़्यादा प्रोटीन शामिल करने में मदद कर सकती है। इससे भी बढ़कर, इस रेसिपी में सिर्फ़ पाँच सामग्री हैं, यानी इसे बनाना और साथ ले जाना बेहद आसान है।","6","1 मफ़िन",
["1 मध्यम केला","1 कप क्विनोआ (पका हुआ)","1/4 कप ग्रीक वनीला दही (वसा रहित)","1/4 कप बादाम बटर","1 कप ब्लूबेरी (ताज़ी)","1 स्प्रे, 0.25 ग्राम नॉनस्टिक कुकिंग स्प्रे"],
["ओवन को 375˚F पर पहले से गरम करें। 6 मफ़िन कप में कुकिंग स्प्रे करें। एक बड़े कटोरे में केला, क्विनोआ, वसा रहित दही और बादाम बटर को मिलने तक चलाएँ। ब्लूबेरी को धीरे से मिलाएँ।","घोल को तैयार मफ़िन कप में चम्मच से डालें। 20 से 25 मिनट तक या सुनहरा भूरा होने और बीच में जम जाने तक बेक करें। पूरी तरह ठंडा होने दें।"]))
r.append(R(6920949,"हरा धनिया और नीबू वाला पुल्ड चिकन","चिकन ब्रेस्ट को स्लो कुकर में पकाने से वह नरम हो जाता है जिससे उसे हाथ से अलग करना और रेशे करना आसान होता है। इस चिकन में तीखे नीबू का स्वाद रचा-बसा है और यह सलाद पत्तों पर या टॉर्टिला में गुआकामोले और सालसा के साथ स्वादिष्ट लगता है।","4","3/4 कप",
["1 छोटा लाल प्याज़ (बारीक कटा हुआ)","1/4 कप नीबू का रस (ताज़ा निचोड़ा हुआ, साथ में 2 बड़े चम्मच)","1/4 छोटा चम्मच कोशर नमक","1 पाउंड बिना हड्डी और बिना त्वचा वाले चिकन ब्रेस्ट (सारा वसा हटाया हुआ)","1 छोटा चम्मच चिली पाउडर","1/2 छोटा चम्मच पिसा जीरा","1 कप कम सोडियम वाला चिकन ब्रॉथ (वसा रहित)","1 छोटा नीबू (परोसने के लिए फाँकों में कटा हुआ)","1/4 कप हरा धनिया (कटा हुआ)"],
["एक मध्यम कटोरे में प्याज़, नीबू का रस और नमक मिलाएँ। प्लास्टिक रैप से ढककर कमरे के तापमान पर 3 से 5 घंटे के लिए एक तरफ़ रख दें, जब तक चिकन पकता है।","चिकन को मध्यम स्लो कुकर में रखें। ऊपर से चिली पाउडर और जीरा छिड़कें। चिकन के चारों ओर चिकन ब्रॉथ डालें। ढककर धीमी (लो) सेटिंग पर 3 से 5 घंटे या चिकन का तापमान 165°F होने तक पकाएँ।","चिकन को स्लो कुकर से निकालें और दो काँटों की मदद से उसके रेशे कर लें। चिकन को कटोरे में रखें और प्याज़-नीबू के मिश्रण के साथ मिलाएँ। नीबू की फाँकों के साथ और ऊपर से कटा हरा धनिया छिड़ककर परोसें।","इलेक्ट्रिक प्रेशर कुकर विकल्प: प्याज़-नीबू का मिश्रण ऊपर बताए अनुसार तैयार करें। चिकन को प्रेशर कुकर में रखें। ऊपर से चिली पाउडर और जीरा छिड़कें। चिकन के चारों ओर चिकन ब्रॉथ डालें। ढक्कन बंद करें। हाई प्रेशर पर 6 मिनट पकाएँ। प्रेशर को 5 मिनट तक प्राकृतिक रूप से निकलने दें, फिर बचा हुआ प्रेशर जल्दी से निकाल दें। ऊपर बताए अनुसार आगे बढ़ें।"]))
r.append(R(6921067,"त्वरित ब्रोकली स्लॉ","यह कुरकुरा साइड डिश पारंपरिक खट्टे-मीठे ब्रोकली सलाद का नया रूप है, लेकिन इसमें अतिरिक्त चीनी नहीं है।","6","1/2 कप",
["1 (12 औंस) बैग ब्रोकली स्लॉ","1/4 कप किशमिश","6 स्लाइस पका टर्की बेकन (कटा हुआ)","1/4 कप लाइट मेयोनेज़","3 बड़े चम्मच वसा रहित सादा दही","2 बड़े चम्मच सेब का सिरका"],
["एक सलाद बाउल में ब्रोकली स्लॉ, किशमिश और टर्की बेकन को मिलाएँ।","एक छोटे कटोरे में मेयोनेज़, दही और सिरके को फेंटकर मिलाएँ। ड्रेसिंग को सलाद पर डालें और लपेटने के लिए मिलाएँ।"]))
r.append(R(6921480,"टोफू स्टर फ्राई","यह परिवार के साथ बाँटने के लिए बेहद त्वरित शाकाहारी रात का खाना है। कभी टोफू के साथ खाना नहीं पकाया? यह रेसिपी शुरुआत के लिए बढ़िया जगह है!","6","1 कप",
["1 पाउंड एक्स्ट्रा फ़र्म टोफू (पानी निथारा हुआ और 1 इंच के टुकड़ों में कटा हुआ)","1/4 कप लाइट तिल-अदरक सलाद ड्रेसिंग","2 छोटे चम्मच तिल का तेल","1 स्प्रे, 0.25 ग्राम नॉनस्टिक कुकिंग स्प्रे","2 कप ब्रोकली के फूल","8 औंस सफ़ेद (बटन) मशरूम (कटे हुए)","1/4 कप बादाम (कतले हुए)","1 कप कम सोडियम वाला वेजिटेबल ब्रॉथ","1 बड़ा चम्मच कॉर्नस्टार्च","1 बड़ा चम्मच सोया सॉस (कम सोडियम वाला)","1 छोटा चम्मच एशियाई शैली की तीखी सॉस","1 बड़ा चम्मच कम कैलोरी वाला ब्राउन शुगर विकल्प","2 फाँक लहसुन (बारीक कटा हुआ)","4 डंठल हरा प्याज़ (स्प्रिंग ओनियन) ((सफ़ेद और हरे दोनों हिस्से), पतले कटे हुए)"],
["एक कटोरे में टोफू और तिल-अदरक सलाद ड्रेसिंग मिलाएँ और 30 मिनट मैरिनेट करें।","टोफू के मैरिनेट हो जाने पर, उसे मैरिनेड से निकालें और मैरिनेड को बचाकर रखें।","कड़ाही या बड़े सॉते पैन में तेज़ आँच पर तिल का तेल और कुकिंग स्प्रे डालें। टोफू डालें और 7-8 मिनट या टोफू के सुनहरा भूरा होने तक स्टर फ्राई करें।","ब्रोकली और मशरूम डालें और 3-4 मिनट स्टर फ्राई करें। हरा प्याज़ और बादाम डालें और 2 मिनट और स्टर फ्राई करें।","एक कटोरे या कप में वेजिटेबल ब्रॉथ, कॉर्नस्टार्च, सोया सॉस, तीखी सॉस, ब्राउन शुगर विकल्प और लहसुन को फेंटें। बचाया हुआ तिल-अदरक ड्रेसिंग मैरिनेड फेंटकर मिलाएँ। मिश्रण को टोफू पर डालें और उबाल आने दें।","आँच धीमी करें और 5 मिनट तक धीमी आँच पर पकाएँ।","परोसने का सुझाव: ब्राउन राइस के ऊपर या लेट्यूस कप में परोसें"]))
r.append(R(6921889,"ग्रिल्ड ज़ुकीनी","यह ग्रिल्ड ज़ुकीनी एक त्वरित साइड डिश है जो सरल, ताज़ा और स्वाद से भरपूर है।","4","1 कप",
["2 मध्यम ज़ुकीनी (गोल टुकड़ों में कटी हुई)","2 बड़े चम्मच जैतून का तेल","1 छोटा चम्मच सूखा थाइम","1/4 छोटा चम्मच नमक","1/2 छोटा चम्मच काली मिर्च"],
["ग्रिल या ग्रिल पैन को 350 डिग्री पर पहले से गरम करें।","एक बड़े कटोरे में ज़ुकीनी के गोल टुकड़ों को जैतून का तेल, सूखा थाइम, नमक और काली मिर्च के साथ मिलाएँ।","चिमटे की मदद से गोल टुकड़ों को ग्रिल पर रखें।","हर तरफ़ 3–4 मिनट ग्रिल करें, जब तक कि वे नरम न हो जाएँ और कुछ जगहों पर जलने के निशान न आ जाएँ।"]))
r.append(R(6921975,"सोका, पोच्ड अंडे, रोस्टेड टमाटर और ताज़ी तुलसी के साथ","सोका, जिसे फ़रिनाटा भी कहा जाता है, बेसन का पतला पैनकेक है जो इतालवी और फ़्रांसीसी दोनों व्यंजनों में आम है। इस रेसिपी में केटी कैवुटो गरम बेसन के क्रेप के टुकड़ों के ऊपर रोस्टेड टमाटर, पोच्ड अंडे और ताज़ी तुलसी डालती हैं। आसान, पहले से तैयार किए जा सकने वाले ब्रंच या हफ़्ते के दिनों के नाश्ते के लिए, घोल बनाकर और अंडे पोच करके एक रात पहले रख लें। पोच्ड अंडों को रातभर रखने के लिए, उन्हें ठंडे पानी से भरे एयरटाइट डिब्बे में डालें और फ्रिज में रखें।","8","1 टुकड़ा सोका + 1 पोच्ड अंडा + 2 बड़े चम्मच रोस्टेड टमाटर + 2 बड़े चम्मच तुलसी",
["1 कप बेसन","1/2 छोटा चम्मच जीरा","1/4 छोटा चम्मच बारीक समुद्री नमक","1 कप गुनगुना पानी","2 बड़े चम्मच एक्स्ट्रा वर्जिन जैतून का तेल (बाँटकर)","1 बड़ा चम्मच सफ़ेद वाइन सिरका","8 बड़े अंडे","1 कप फ़ायर-रोस्टेड टमाटर","1 कप ताज़ी तुलसी (कटी हुई)","1/4 छोटा चम्मच ताज़ी पिसी काली मिर्च"],
["10 इंच की कास्ट-आयरन कड़ाही को अपने ओवन के हीटिंग एलिमेंट से लगभग 12 इंच दूर रखें और ओवन को \"ब्रॉइल\" पर सेट करें।","एक छोटे कटोरे में बेसन, जीरा और नमक को फेंटकर मिलाएँ। गुठलियाँ हटाने के लिए तेज़ी से फेंटते हुए धीरे-धीरे पानी की धार डालें, फिर 1 बड़ा चम्मच जैतून का तेल मिलाएँ। कटोरे को ढककर कम से कम 15 मिनट के लिए एक तरफ़ रख दें। (या इसे फ्रिज में 12 घंटे तक रखें।) घोल पतला, पैनकेक के घोल जैसी गाढ़ाई वाला होना चाहिए।","घोल के आराम कर लेने के बाद, गरम कड़ाही को सावधानी से ओवन से निकालें। कड़ाही में बचा हुआ 1 बड़ा चम्मच जैतून का तेल डालें और सोका का घोल उसमें डालें। 8–10 मिनट तक या सोका के किनारे भूरे होने और बीच का हिस्सा जमने तक ब्रॉइल करें।","इस बीच, एक बड़े बरतन की तली में धातु की छलनी रखें, बरतन को 2/3 पानी से भरें और सिरका डालें। हर अंडे को एक छोटे कटोरे में तोड़ें। बरतन को मध्यम-तेज़ आँच पर रखें और सिरके और पानी को धीमे उबाल पर लाएँ। लंबे हत्थे वाले चम्मच से पानी को चौड़े, गोलाकार तरीके से चलाकर भँवर बनाएँ। जल्दी से, जब तक भँवर चल रहा हो, अंडों को एक-एक करके डालें। जब सारे अंडे पानी में आ जाएँ, तो बिना चलाए पोच करें जब तक कि सफ़ेदी जम न जाए और ज़र्दी बहने वाली न रहे, लगभग 4–6 मिनट। चिमटे की मदद से अंडों वाली छलनी को पानी से सावधानी से बाहर उठाएँ।","सोका को ओवन से निकालें और 8 तिकोने टुकड़ों में काट लें। परोसने के लिए, 8 प्लेटों में से हर एक पर सोका का एक टुकड़ा रखें और हर सर्विंग के ऊपर 1 पोच्ड अंडा, 2 बड़े चम्मच रोस्टेड टमाटर और 2 बड़े चम्मच कटी तुलसी डालें। सर्विंग पर काली मिर्च छिड़कें।"]))
r.append(R(6922278,"फूलगोभी राइस के साथ झींगा पाएया","यह झींगा पाएया सॉसेज, शिमला मिर्च, हल्दी और पेपरिका के स्वाद से भरपूर है। राइस जैसी कटी फूलगोभी का इस्तेमाल इसे पारंपरिक स्पैनिश पाएया का कम कार्बोहाइड्रेट वाला विकल्प बनाता है।","6","1 कप",
["1 स्प्रे, 0.25 ग्राम नॉनस्टिक कुकिंग स्प्रे","1 बड़ा प्याज़ (कटा हुआ)","1 मध्यम लाल शिमला मिर्च (बीज निकालकर कटी हुई)","1 (3 औंस) पूरी तरह पका हुआ अंडुइयेट या चोरिज़ो चिकन सॉसेज (कटा हुआ)","2 फाँक लहसुन (बारीक कटा हुआ)","1/2 छोटा चम्मच हल्दी","1/2 छोटा चम्मच पेपरिका","3 कप कम सोडियम वाला चिकन ब्रॉथ","1/2 छोटा चम्मच नमक","6 कप ताज़ा या फ्रोज़न फूलगोभी राइस","1/2 छोटा चम्मच काली मिर्च (पिसी हुई)","12 औंस कच्चा झींगा (छिला और नस निकाला हुआ)"],
["एक बड़ी कड़ाही में मध्यम-तेज़ आँच पर कुकिंग स्प्रे डालें। सॉसेज, प्याज़, शिमला मिर्च और लहसुन डालें। प्याज़ के कैरेमलाइज़ होना शुरू होने तक, लगभग 8 मिनट भूनें।","हल्दी और पेपरिका मिलाएँ। ब्रॉथ, फूलगोभी राइस, नमक और काली मिर्च डालें। उबाल लाएँ, फिर आँच धीमी करें, ढक दें और लगभग 5 मिनट धीमी आँच पर पकाएँ।","पैन में झींगा डालें, फिर ढककर झींगा के बीच में बस अपारदर्शी होने तक, लगभग 6 मिनट पकाएँ।"]))
r.append(R(6923281,"बारबेक्यू चिकन पिज़्ज़ा","इस पिज़्ज़ा को ढेर सारे बगीचे के सलाद के साथ परोसें, जिस पर कम वसा वाली रैंच ड्रेसिंग हल्के से डाली गई हो। यह त्वरित, आसान और किफ़ायती भोजन है!","8","1 टुकड़ा",
["1 स्प्रे, 0.25 ग्राम नॉनस्टिक कुकिंग स्प्रे","1/2 पाउंड बिना हड्डी और बिना त्वचा वाला चिकन ब्रेस्ट","1/4 छोटा चम्मच नमक","1/4 छोटा चम्मच काली मिर्च","1/4 कप शुगर-फ्री खुबानी का जैम","1/4 कप बारबेक्यू सॉस","1/2 छोटा चम्मच तीखी सॉस","1 12 इंच का पहले से पैक साबुत गेहूँ का पिज़्ज़ा बेस","1 कप कद्दूकस की हुई गाजर","1/2 मध्यम लाल प्याज़ (पतला कटा हुआ)","1/2 कप कम वसा वाला कद्दूकस किया इतालवी शैली का चीज़","1/2 छोटा चम्मच सूखा अजवायन"],
["ओवन को 375°F पर पहले से गरम करें। बेकिंग शीट पर कुकिंग स्प्रे करें।","चिकन के दोनों तरफ़ नमक और काली मिर्च लगाएँ।","चिकन को तैयार बेकिंग शीट पर रखें और 25 मिनट तक या रस साफ़ निकलने तक बेक करें। चिकन को ओवन से निकालें और आधे इंच के टुकड़ों में काट लें।","एक छोटे सॉसपैन में शुगर-फ्री खुबानी का जैम, बारबेक्यू सॉस और तीखी सॉस मिलाएँ। उबाल आने दें।","सॉस को पिज़्ज़ा बेस पर चम्मच से फैलाएँ। बेस के ऊपर पका हुआ चिकन, कटा प्याज़, गाजर और चीज़ डालें। चीज़ पर सूखा अजवायन छिड़कें।","पिज़्ज़ा को 20-25 मिनट तक या चीज़ के पिघलने और बुलबुले उठने तक बेक करें।"]))
